/* Feathered edge softness; preserve alignment and avoid a hard focus-window boundary. */
function softEdgeBlur(ctx,strength){if(strength<=0)return;const source=ctx.canvas;let copy=source._softEdgeBuffer;if(!copy){copy=document.createElement('canvas');copy.width=source.width;copy.height=source.height;source._softEdgeBuffer=copy}const b=copy.getContext('2d');b.clearRect(0,0,copy.width,copy.height);b.save();b.filter=`blur(${strength}px)`;b.drawImage(source,0,0);b.restore();b.save();b.globalCompositeOperation='destination-in';b.translate(copy.width/2,copy.height/2);b.scale(1,.72);const gradient=b.createRadialGradient(0,0,180,0,0,520);gradient.addColorStop(0,'#ffffff00');gradient.addColorStop(.35,'#ffffff00');gradient.addColorStop(.75,'#ffffffaa');gradient.addColorStop(1,'#ffffff');b.fillStyle=gradient;b.fillRect(-copy.width,-copy.height*2,copy.width*2,copy.height*4);b.restore();ctx.drawImage(copy,0,0)}
